import { useState, useEffect } from "react";

export async function fetchUsers() {
  await new Promise((r) => setTimeout(r, 100));
  return ["Ada", "Linus", "Grace"];
}

export function App() {
  const [users, setUsers] = useState(null);
  useEffect(() => {
    let alive = true;
    fetchUsers().then((u) => { if (alive) setUsers(u); });
    return () => { alive = false; };
  }, []);
  if (!users) return <p id="status">loading</p>;
  return (
    <ul id="users">
      {users.map((u) => (
        <li key={u}>{u}</li>
      ))}
    </ul>
  );
}

