import { useState } from "react";

function useCounter(initial) {
  const [value, setValue] = useState(initial);
  return {
    value,
    increment: () => setValue(value + 1),
    decrement: () => setValue(value - 1),
    reset: () => setValue(initial),
  };
}

export function App() {
  const { value, increment, decrement, reset } = useCounter(10);
  return (
    <>
      <span id="val">{value}</span>
      <button id="inc" onClick={increment}>+</button>
      <button id="dec" onClick={decrement}>-</button>
      <button id="rst" onClick={reset}>reset</button>
    </>
  );
}

