import { useState } from "react";

export function App() {
  const [email, setEmail] = useState("");
  const [status, setStatus] = useState(null);
  const submit = (e) => {
    e.preventDefault();
    if (email.includes('@') && email.includes('.')) setStatus({ ok: true, email });
    else setStatus({ err: true });
  };
  return (
    <form onSubmit={submit}>
      <input id="email" value={email} onChange={(e) => setEmail(e.target.value)} />
      <button id="go" type="submit">Sign up</button>
      {status && status.ok && <p id="ok">Welcome, {status.email}</p>}
      {status && status.err && <p id="err">Invalid email</p>}
    </form>
  );
}
